/** Опции п.3 для макетов «приказ/исковое … с 1 по 8». */
export const MAGISTRATE_OPTS_1_TO_8 = ['1', '2', '3.1', '5.1', '6.1', '6.3', '7.1', '8.1'];

function downloadPdf(docDefinition, filename) {
  pdfMake.createPdf(docDefinition).download(filename);
}

/**
 * Макет «приказ для мирового - 9»:
 * вар.1 + опция 9 + 3.3 вар.2 (только кредит) + 3.3.1 «к поручителям» или «нет».
 */
export function matchesMagistrateOpt9(form = {}) {
  if (form.statementType !== 'a') return false;
  if (String(form.requirements || '') !== '9') return false;
  const loan = form.loanInfo || {};
  if (loan.loanClaimType !== 'b') return false;
  return loan.guarantorClaim === 'a' || loan.guarantorClaim === 'c';
}

export function matchesMagistrateOpts1to8(form = {}) {
  if (form.statementType !== 'a') return false;
  return MAGISTRATE_OPTS_1_TO_8.includes(String(form.requirements || ''));
}

/** Вар.2 + п.1* вар.2 (п.3 виден) + опции 1–8: «исковое для района - с 1 по 8». */
export function matchesDistrictClaim1to8(form = {}) {
  if (form.statementType !== 'b') return false;
  // как showRequirements в index.vue: п.3 только при statementIndividual === 'b'
  if (form.statementIndividual !== 'b') return false;
  return MAGISTRATE_OPTS_1_TO_8.includes(String(form.requirements || ''));
}

/**
 * Вар.2 + опция 9 + п.3.3 вар.1/2:
 * «исковое для района - 9 (кредит + залог)».
 */
export function matchesDistrictClaim9CreditPledge(form = {}) {
  if (form.statementType !== 'b') return false;
  if (form.statementIndividual !== 'b') return false;
  if (String(form.requirements || '') !== '9') return false;
  const loanClaimType = form.loanInfo?.loanClaimType;
  return loanClaimType === 'a' || loanClaimType === 'b';
}

/**
 * Вар.2 + опция 9 + п.3.3 вар.3:
 * «исковое для района - 9 (только залог)».
 */
export function matchesDistrictClaim9PledgeOnly(form = {}) {
  if (form.statementType !== 'b') return false;
  if (form.statementIndividual !== 'b') return false;
  if (String(form.requirements || '') !== '9') return false;
  return form.loanInfo?.loanClaimType === 'c';
}

/** Вар.4/5 + опции 1 или 2: «исковое для арбитража - 1+2». */
export function matchesArbitrationClaim1to2(form = {}) {
  if (!['d', 'e'].includes(form.statementType)) return false;
  if (form.statementIndividual !== 'b') return false;
  const req = String(form.requirements || '');
  return req === '1' || req === '2';
}

