export function downloadPenaltyXlsx(form) {
  const title = 'Расчет неустойки';
  const penalty = buildPenaltyRows(form);
  const worksheet = XLSX.utils.aoa_to_sheet(penalty.rows);
  worksheet['!merges'] = penalty.merges;
  worksheet['!cols'] = penalty.cols;
  applyPenaltyStyles(XLSX, worksheet, penalty);
  const workbook = XLSX.utils.book_new();
  XLSX.utils.book_append_sheet(workbook, worksheet, 'расчет');
  XLSX.writeFile(workbook, `${title}.xlsx`);
}

/** Вар.1: заявление + проект приказа + пени (3 файла) по макетам 1–8 / 9. */
export function downloadMagistrateOrderPack(form) {
  if (matchesMagistrateOpt9(form)) {
    downloadStatementMagistrate9Pdf(form);
    downloadCourtOrderMagistrate9Pdf(form);
    downloadPenaltyXlsx(form);
    return 'magistrate-9';
  }
  if (matchesMagistrateOpts1to8(form)) {
    downloadStatementMagistrate1to8Pdf(form);
    downloadCourtOrderMagistrate1to8Pdf(form);
    downloadPenaltyXlsx(form);
    return 'magistrate-1-8';
  }
  return null;
}

/** Вар.2: исковое + пени (без проекта приказа) по макетам района 9 / 1–8. */
export function downloadDistrictClaimPack(form) {
  if (matchesDistrictClaim9PledgeOnly(form)) {
    downloadStatementDistrict9PledgeOnlyPdf(form);
    // п.3.3 вар.3 + «без неустоек» → без файла пени
    const withoutPenalties = (form?.pledgeContracts || []).some((p) => p.coverageMode === 'withoutPenalty');
    if (!withoutPenalties && form?.penaltyLoan?.hasPenalty === 'a') {
      downloadPenaltyXlsx(form);
    }
    return 'district-9-pledge-only';
  }
  if (matchesDistrictClaim9CreditPledge(form)) {
    downloadStatementDistrict9CreditPledgePdf(form);
    downloadPenaltyXlsx(form);
    return 'district-9-credit-pledge';
  }
  if (matchesDistrictClaim1to8(form)) {
    downloadStatementDistrict1to8Pdf(form);
    downloadPenaltyXlsx(form);
    return 'district-1-8';
  }
  return null;
}

/** Вар.4/5: исковое + пени по макетам арбитража. */
export function downloadArbitrationClaimPack(form) {
  if (matchesArbitrationClaim9PledgeOnly(form)) {
    downloadStatementArbitrationClaim9PledgeOnlyPdf(form);
    const withoutPenalties = (form?.pledgeContracts || []).some((p) => p.coverageMode === 'withoutPenalty');
    if (!withoutPenalties && form?.penaltyLoan?.hasPenalty === 'a') {
      downloadPenaltyXlsx(form);
    }
    return 'arbitration-claim-9-pledge-only';
  }
  if (matchesArbitrationClaim9CreditPledge(form)) {
    downloadStatementArbitrationClaim9CreditPledgePdf(form);
    downloadPenaltyXlsx(form);
    return 'arbitration-claim-9-credit-pledge';
  }
  if (matchesArbitrationClaim1to2(form)) {
    downloadStatementArbitrationClaim1to2Pdf(form);
    downloadPenaltyXlsx(form);
    return 'arbitration-claim-1-2';
  }
  if (matchesArbitrationClaim3to8(form)) {
    downloadStatementArbitrationClaim3to8Pdf(form);
    downloadPenaltyXlsx(form);
    return 'arbitration-claim-3-8';
  }
  return null;
}

/**
 * Вар.6: изменение размера + пени (+ соответчики при необходимости).
 * Район — гражданин в 8**; арбитраж — все юрлица/ИП.
 */
export function downloadDistrictRecalcPack(form) {
  if (matchesDistrictChangeClaim9CreditPledge(form)) {
    downloadChangeClaimDistrict9CreditPledgePdf(form);
    downloadPenaltyXlsx(form);
    return 'district-recalc-9-credit-pledge';
  }
  if (matchesDistrictChangeClaim1to8(form)) {
    downloadChangeClaimDistrict1to8Pdf(form);
    downloadPenaltyXlsx(form);
    if (needsAttractCodefendants(form)) {
      downloadAttractCodefendantsDistrict1to8Pdf(form);
      return 'district-recalc-1-8-codefendants';
    }
    return 'district-recalc-1-8';
  }
  if (matchesArbitrationChangeClaim9CreditPledge(form)) {
    downloadChangeClaimArbitration9CreditPledgePdf(form);
    downloadPenaltyXlsx(form);
    return 'arbitration-recalc-9-credit-pledge';
  }
  if (matchesArbitrationChangeClaim1to2(form)) {
    downloadChangeClaimArbitration1to2Pdf(form);
    downloadPenaltyXlsx(form);
    if (needsAttractCodefendants(form)) {
      downloadAttractCodefendantsArbitration1to2Pdf(form);
      return 'arbitration-recalc-1-2-codefendants';
    }
    return 'arbitration-recalc-1-2';
  }
  if (matchesArbitrationChangeClaim3to8(form)) {
    downloadChangeClaimArbitration3to8Pdf(form);
    downloadPenaltyXlsx(form);
    return 'arbitration-recalc-3-8';
  }
  return null;
}

/** Вар.3: заявление о выдаче с/приказа + пени (2 файла). */
export function downloadArbitrationOrderPack(form) {
  if (matchesArbitrationOrder9(form)) {
    downloadStatementArbitration9Pdf(form);
    downloadPenaltyXlsx(form);
    return 'arbitration-9';
  }
  if (matchesArbitrationOrder1to2(form)) {
    downloadStatementArbitration1to2Pdf(form);
    downloadPenaltyXlsx(form);
    return 'arbitration-1-2';
  }
  if (matchesArbitrationOrder3to8(form)) {
    downloadStatementArbitration3to8Pdf(form);
    downloadPenaltyXlsx(form);
    return 'arbitration-3-8';
  }
  return null;
}
