/**
 * Суммы для макетов «изменение размера …»:
 * - вар.1/2 п.1.2 → долг + пеня из нового расчёта пени;
 * - вар.3 п.1.2 → долг + пеня из полей п.1.2 (контррасчёт); даты периода — плейсхолдер «дата».
 */

function num(value) {
  const n = Number(value);
  return Number.isFinite(n) && n > 0 ? n : 0;
}

/** ЖКУ / лицевой: housingPenalty + опционально уже посчитанные даты периода. */
export function resolveChangeClaimHousingAmounts(
  form = {},
  housingPenalty = {},
  { penaltyFrom = '', penaltyTo = '', continueFrom = '' } = {}
) {
  const court = form.courtDocuments || {};
  const reason = String(court.recalculateReason || 'a');

  if (reason === 'c') {
    const principal = num(court.counterDebtAmount);
    const penaltyTotal = court.penaltyNotClaimed ? 0 : num(court.counterPenaltyAmount);
    return {
      reason,
      principal,
      penaltyTotal,
      claimTotal: principal + penaltyTotal,
      penaltyFrom: '',
      penaltyTo: '',
      continueFrom: '',
    };
  }

  const principal = num(housingPenalty.principalTotal);
  const penaltyTotal = num(housingPenalty.penaltyTotal);
  return {
    reason,
    principal,
    penaltyTotal,
    claimTotal: principal + penaltyTotal,
    penaltyFrom: penaltyFrom || '',
    penaltyTo: penaltyTo || '',
    continueFrom: continueFrom || '',
  };
}

/** Кредит / ссудный: суммы из loanCalc, для вар.3 — из п.1.2. */
export function resolveChangeClaimLoanAmounts(
  form = {},
  { debtAmount = 0, penaltyAmount = 0, penaltyFrom = '', penaltyTo = '' } = {}
) {
  const court = form.courtDocuments || {};
  const reason = String(court.recalculateReason || 'a');

  if (reason === 'c') {
    const debt = num(court.counterDebtAmount);
    const penalty = court.penaltyNotClaimed ? 0 : num(court.counterPenaltyAmount);
    return {
      reason,
      debtAmount: debt,
      penaltyAmount: penalty,
      claimTotal: debt + penalty,
      penaltyFrom: '',
      penaltyTo: '',
    };
  }

  const debt = num(debtAmount);
  const penalty = num(penaltyAmount);
  return {
    reason,
    debtAmount: debt,
    penaltyAmount: penalty,
    claimTotal: debt + penalty,
    penaltyFrom: penaltyFrom || '',
    penaltyTo: penaltyTo || '',
  };
}
