function emptyCells(len = 13) {
  return Array.from({ length: len }, () => '');
}

function formatMoney(value) {
  const num = Number(value);
  if (!Number.isFinite(num)) return '';
  return num.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
}

function formatRate(rate) {
  const num = Number(rate);
  if (!Number.isFinite(num)) return '';
  return `${(num * 100).toFixed(2)}%`;
}

function formatFraction(fraction, label) {
  if (label && String(label).includes('/')) return String(label).trim();
  if (fraction == null || !Number.isFinite(Number(fraction))) return '';
  const n = Number(fraction);
  // 1/130 → показать как дробь, если близко к известным
  const dens = [130, 300, 150, 360];
  for (const d of dens) {
    if (Math.abs(n * d - 1) < 1e-9) return `1/${d}`;
  }
  return String(n);
}

function buildPeriodRows(period, { profile, lastCol }) {
  if (!period || period.excludedAfterAsOf || !period.accrual) return [];

  const is31 = profile === '3.1';
  const penaltyCol = is31 ? 10 : 9;
  const rows = [];
  const accrualRow = emptyCells(lastCol + 1);
  accrualRow[0] = period.accrual.date || '';
  accrualRow[1] = formatMoney(period.accrual.amount);
  accrualRow[5] = period.penaltyStartDate || '';
  rows.push(accrualRow);

  const before = (period.paymentRows || []).filter((p) => p.appliedBeforePenalty && !p.ignoredAfterAsOf);
  const after = (period.paymentRows || []).filter((p) => !p.appliedBeforePenalty && !p.ignoredAfterAsOf);

  for (const payment of before) {
    const row = emptyCells(lastCol + 1);
    row[3] = payment.date || '';
    row[4] = formatMoney(payment.amount);
    rows.push(row);
  }

  const segments = period.segments || [];
  let afterIdx = 0;

  for (const segment of segments) {
    const segRow = emptyCells(lastCol + 1);
    segRow[2] = formatMoney(segment.debt);
    segRow[5] = segment.from || '';
    segRow[6] = segment.to || '';
    segRow[7] = segment.days != null ? String(segment.days) : '';
    if (is31) {
      segRow[8] = formatFraction(segment.rateFraction, segment.rateLabel);
      segRow[9] = formatRate(segment.keyRate);
    } else {
      segRow[8] = formatRate(segment.rate);
    }
    segRow[penaltyCol] = formatMoney(segment.penalty);
    rows.push(segRow);

    if (segment.closedByPayment && after[afterIdx]) {
      const payment = after[afterIdx];
      afterIdx += 1;
      const payRow = emptyCells(lastCol + 1);
      payRow[3] = payment.date || '';
      payRow[4] = formatMoney(payment.amount);
      rows.push(payRow);
    }
  }

  while (afterIdx < after.length) {
    const payment = after[afterIdx];
    afterIdx += 1;
    const payRow = emptyCells(lastCol + 1);
    payRow[3] = payment.date || '';
    payRow[4] = formatMoney(payment.amount);
    rows.push(payRow);
  }

  if (!segments.length && period.remainingDebt > 0) {
    const debtRow = emptyCells(lastCol + 1);
    debtRow[2] = formatMoney(period.remainingDebt);
    rows.push(debtRow);
  }

  return rows;
}

/**
 * @param {{ skanReport?: { housingPenalty?: object }, housingPenalty?: object }|object} [formOrResult]
 */
export function buildPenaltyRows(formOrResult = {}) {
  const result =
    formOrResult?.skanReport?.housingPenalty ||
    formOrResult?.housingPenalty ||
    (Array.isArray(formOrResult?.periods) ? formOrResult : null);

  const profile = result?.profile || 'default';
  const is31 = profile === '3.1';
  const is32 = profile === '3.2';
  const lastCol = is31 ? 10 : 9;
  const penaltyCol = is31 ? 10 : 9;

  // 3.1 — два столбца ставки; 3.2 — один «ставка неустойки, %»; иначе — ключевая ЦБ
  const headerRate = is31
    ? ['ставка неустойки', '', 'сумма неустойки, руб.']
    : is32
      ? ['ставка неустойки, %', 'сумма неустойки, руб.', '']
      : ['ключевая ставка ЦБ РФ, %', 'сумма неустойки, руб.', ''];

  const subRate = is31
    ? ['доля от ключевой ставки', 'ключевая ставка ЦБ РФ, %', '']
    : ['', '', ''];

  const rows = [
    ['Расчет неустойки', '', '', '', '', '', '', '', '', '', '', '', ''],
    ['', '', '', '', '', '', '', '', '', '', '', '', ''],
    [
      'начисленная плата',
      '',
      'задолженность, руб.',
      'произведенная оплата',
      '',
      'просрочка оплаты/возврата',
      '',
      '',
      ...headerRate,
      '',
      '',
    ].slice(0, 13),
    [
      'дата начисления',
      'сумма, руб.',
      '',
      'дата',
      'сумма, руб.',
      'с',
      'по',
      'в днях',
      ...subRate,
      '',
      '',
    ].slice(0, 13),
  ];

  const dataStartRow = rows.length;
  const periods = result?.periods || [];
  for (const period of periods) {
    buildPeriodRows(period, { profile, lastCol }).forEach((row) => rows.push(row));
  }

  if (rows.length === dataStartRow) {
    rows.push(emptyCells(lastCol + 1));
  }

  const dataEndRow = rows.length - 1;
  const totalRow = rows.length;
  const total = emptyCells(lastCol + 1);
  total[0] = 'Итого:';
  total[2] = formatMoney(result?.principalTotal ?? 0);
  total[penaltyCol] = formatMoney(result?.penaltyTotal ?? 0);
  rows.push(total);

  const merges = [
    { s: { c: 0, r: 0 }, e: { c: lastCol, r: 0 } },
    { s: { c: 0, r: 2 }, e: { c: 1, r: 2 } },
    { s: { c: 2, r: 2 }, e: { c: 2, r: 3 } },
    { s: { c: 3, r: 2 }, e: { c: 4, r: 2 } },
    { s: { c: 5, r: 2 }, e: { c: 7, r: 2 } },
  ];

  if (is31) {
    // «ставка неустойки» на два столбца; «сумма неустойки» на две строки
    merges.push({ s: { c: 8, r: 2 }, e: { c: 9, r: 2 } });
    merges.push({ s: { c: 10, r: 2 }, e: { c: 10, r: 3 } });
  } else {
    merges.push({ s: { c: 8, r: 2 }, e: { c: 8, r: 3 } });
    merges.push({ s: { c: 9, r: 2 }, e: { c: 9, r: 3 } });
  }

  const cols = [
    { wch: 16 },
    { wch: 12 },
    { wch: 14 },
    { wch: 12 },
    { wch: 12 },
    { wch: 12 },
    { wch: 12 },
    { wch: 9 },
    { wch: is31 ? 18 : 16 },
    { wch: is31 ? 16 : 16 },
    { wch: is31 ? 16 : 10 },
    { wch: 10 },
    { wch: 10 },
  ];

  return {
    rows,
    merges,
    cols,
    headerStartRow: 2,
    headerEndRow: 3,
    dataStartRow,
    dataEndRow,
    totalRow,
    lastCol,
    profile,
  };
}

function border(style = 'thin') {
  const side = { style, color: { rgb: '000000' } };
  return { top: side, bottom: side, left: side, right: side };
}

const HEADER_STYLE = {
  font: { bold: true },
  alignment: { horizontal: 'center', vertical: 'center', wrapText: true },
  border: border(),
};

const DATA_STYLE = {
  alignment: { horizontal: 'center', vertical: 'center' },
  border: border(),
};

const TOTAL_LABEL_STYLE = {
  font: { bold: true },
  alignment: { horizontal: 'left', vertical: 'center' },
};

const TOTAL_DATA_STYLE = {
  alignment: { horizontal: 'center', vertical: 'center' },
};

const TITLE_STYLE = {
  font: { bold: true, sz: 14 },
  alignment: { horizontal: 'center', vertical: 'center' },
};

export function applyPenaltyStyles(XLSX, worksheet, meta) {
  const { headerStartRow, totalRow, lastCol } = meta;

  const setStyle = (r, c, style) => {
    const addr = XLSX.utils.encode_cell({ r, c });
    if (!worksheet[addr]) worksheet[addr] = { t: 's', v: '' };
    worksheet[addr].s = style;
  };

  setStyle(0, 0, TITLE_STYLE);

  for (let r = headerStartRow; r <= totalRow; r += 1) {
    for (let c = 0; c <= lastCol; c += 1) {
      const isHeaderRow = r === headerStartRow || r === headerStartRow + 1;
      const isTotalRow = r === totalRow;
      if (isHeaderRow) {
        setStyle(r, c, HEADER_STYLE);
      } else if (isTotalRow && c === 0) {
        setStyle(r, c, TOTAL_LABEL_STYLE);
      } else if (isTotalRow) {
        setStyle(r, c, TOTAL_DATA_STYLE);
      } else {
        setStyle(r, c, DATA_STYLE);
      }
    }
  }
}
