/**
 * Макет: «исковое для арбитража - 1+2.docx»
 * Вар.4/5 + опции 1 или 2. Без отсебятины.
 */
import { formatDutyAmount } from '../utils/calculateStateDuty';
import { addDays, formatRuDate, parseRuDate } from '../utils/calculateHousingPenalty';
import { parseRuAddressParts } from '../utils/resolveSoyCourt';
import { debtorDisplayName, joinDebtorNames, resolveDebtors } from '../utils/resolveDebtors';

const PLACEHOLDER_COLOR = '#C00000';
/** В образце госпошлина фиксирована: 10 000 руб. */
const ARBITRATION_CLAIM_DUTY = '10\u00a0000';

function label(text) {
  return { text };
}

function placeholder(text) {
  return { text, italics: true, color: PLACEHOLDER_COLOR };
}

function plain(text) {
  return { text };
}

function field(value, placeholderText) {
  const text = value != null ? String(value).trim() : '';
  return text ? plain(text) : placeholder(placeholderText);
}

function headerLine(children) {
  return { text: children, alignment: 'right' };
}

function bodyParagraph(children) {
  return { text: children, alignment: 'justify', margin: [24, 0, 0, 8] };
}

function moneyField(value, placeholderText) {
  const n = Number(value);
  return n > 0 ? label(formatDutyAmount(n)) : placeholder(placeholderText);
}

function optionalHeaderLine(text) {
  const value = text != null ? String(text).trim() : '';
  return value ? [headerLine([plain(value)])] : [];
}

function penaltyPeriodRange(housingPenalty) {
  const periods = (housingPenalty?.periods || []).filter(
    (p) => !p.excludedAfterAsOf && p.penaltyTotal > 0 && p.segments?.length
  );
  if (!periods.length) return { from: '', to: '' };
  const from = periods[0].segments[0]?.from || periods[0].penaltyStartDate || '';
  const last = periods[periods.length - 1];
  const lastSeg = last.segments[last.segments.length - 1];
  const to = lastSeg?.to || housingPenalty.asOfDate || '';
  return { from, to };
}

function dayAfter(ruDate) {
  const d = parseRuDate(ruDate);
  return d ? formatRuDate(addDays(d, 1)) : '';
}

/** Образец: вставка, если пеня на задолженность, начисленную с 1.01.2027. */
function hasPenaltyOnDebtFrom2027(housingPenalty) {
  const cutoff = parseRuDate('01.01.2027');
  if (!cutoff) return false;
  return (housingPenalty?.periods || []).some((p) => {
    if (p.excludedAfterAsOf) return false;
    const accrual = parseRuDate(p.accrual?.date);
    return accrual && accrual.getTime() >= cutoff.getTime();
  });
}

function resolveHouseAddress(form, debtor) {
  return String(form.premisesAddress || '').trim() || String(debtor.address || '').trim();
}

function resolvePremisesNumber(form, debtor) {
  const fromHouse = resolveHouseAddress(form, debtor);
  const fromDebtor = parseRuAddressParts(debtor.address || '').flat;
  const fromPremises = parseRuAddressParts(fromHouse).flat;
  const flat = fromPremises || fromDebtor;
  if (flat) {
    return (
      flat
        .replace(/^(кв\.|квартира|помещ\.|помещение|ком\.|комната)\s*/i, '')
        .trim() || flat
    );
  }
  const match = fromHouse.match(
    /(?:помещ\.|помещение|кв\.|квартира)\s*([0-9A-Za-zА-Яа-я/-]+)/i
  );
  return match ? match[1] : '';
}

/** Шапка ответчика: только заполненные поля (наименование / ОГРН / ИНН / адрес). */
function defendantHeaderLines(person) {
  const name = String(person.fio || '').trim();
  const inn = String(person.inn || '').trim();
  const ogrn = String(person.ogrn || '').trim();
  const address = String(person.address || '').trim();
  const lines = [];
  if (name) lines.push(headerLine([plain(name)]));
  else if (inn) lines.push(headerLine([plain(`ИНН ${inn}`)]));
  if (ogrn) lines.push(headerLine([plain(`ОГРН ${ogrn}`)]));
  if (name && inn) lines.push(headerLine([plain(`ИНН ${inn}`)]));
  if (address) lines.push(headerLine([plain(address)]));
  return lines;
}

export function buildStatementArbitrationClaim1to2PdfDoc(form = {}) {
  const claimant = form.claimant || {};
  const bank = form.bankDetails || {};
  const debtors = resolveDebtors(form);
  const debtor = debtors[0] || {};
  const signerFio = form.signer && form.signer.fio;
  const housingPenalty = (form.skanReport && form.skanReport.housingPenalty) || {};
  const claimantName = String(claimant.name || bank.recipientName || '').trim();
  const claimantInn = String(claimant.inn || bank.inn || '').trim();
  const claimantAddress = String(claimant.address || '').trim();
  const requirements = String(form.requirements || '');
  const isOpt2 = requirements === '2';

  const debtorNames = joinDebtorNames(debtors);
  const ownerName = debtorDisplayName(debtor);
  const houseAddress = resolveHouseAddress(form, debtor);
  const premisesNumber = resolvePremisesNumber(form, debtor);
  const penaltyRange = penaltyPeriodRange(housingPenalty);
  const continueFrom = dayAfter(penaltyRange.to) || penaltyRange.to;
  const hasDebt = Number(housingPenalty.principalTotal) > 0;
  const showKeyRateOnDecision = hasPenaltyOnDebtFrom2027(housingPenalty);

  const defendantBlocks = debtors.flatMap((d, index) => {
    const lines = defendantHeaderLines(d);
    return index < debtors.length - 1 ? [...lines, headerLine([plain(' ')])] : lines;
  });

  const content = [
    // Только «Арбитражный суд» — субъект/адрес без плейсхолдеров и без СОЮ
    headerLine([label('Арбитражный суд')]),
    headerLine([plain(' ')]),
    headerLine([label('Истец:')]),
    ...optionalHeaderLine(claimantName),
    ...(claimantInn ? [headerLine([plain(`ИНН ${claimantInn}`)])] : []),
    ...optionalHeaderLine(claimantAddress),
    headerLine([plain(' ')]),
    headerLine([label('Ответчик:')]),
    ...defendantBlocks,

    {
      text: 'Исковое заявление',
      alignment: 'center',
      bold: true,
      margin: [0, 24, 0, 24],
    },

    // Образец: «такая-то»; если наименования нет — ИНН (как в шапке истца)
    bodyParagraph([
      field(claimantName || claimantInn, 'такая-то'),
      plain(
        ' исполняет обязанности по управлению и текущему ремонту в отношении многоквартирного дома по адресу: '
      ),
      field(houseAddress, 'адрес'),
      plain('.'),
    ]),
    bodyParagraph([
      field(ownerName, 'такой-то'),
      plain(' является собственником нежилого помещения '),
      field(premisesNumber, 'номер'),
      plain(' в этом доме.'),
    ]),
    bodyParagraph([
      plain(
        'Из ст. 210, 249 ГК РФ, ч. 3 ст. 30, ст. 36, 37, 39, 154, 158 ЖК РФ следует, что собственник помещения в многоквартирном доме, в том числе собственник нежилого помещения, обязан нести расходы на содержание принадлежащего ему помещения, а также участвовать в расходах на содержание общего имущества в многоквартирном доме соразмерно своей доле в праве общей собственности на это имущество путем внесения платы за содержание и текущий ремонт общего имущества, коммунальные ресурсы, потребляемые при использовании и содержании общего имущества и взносов на капитальный ремонт.'
      ),
    ]),
    isOpt2
      ? bodyParagraph([
          plain(
            'Данная обязанность возникает в силу закона и не обусловлена наличием договорных отношений собственника нежилого помещения с региональным оператором капитального ремонта общего имущества в МКД.'
          ),
        ])
      : bodyParagraph([
          plain(
            'Данная обязанность возникает в силу закона и не обусловлена наличием договорных отношений собственника нежилого помещения с управляющей компанией или товариществом собственников жилья.'
          ),
        ]),
    bodyParagraph([
      plain(
        'Аналогичная обязанность возлагается и на обладателя права оперативного управления (Постановление Конституционного Суда РФ от 29.01.2018 N 5-П, Определения Верховного Суда РФ от 28.11.2017 N 305-ЭС17-10430, от 12.10.2021 N 305-ЭС21-10209 и др.)'
      ),
    ]),
    bodyParagraph([
      plain(
        'Согласно ч. 1 ст. 155 ЖК РФ плата за принадлежащее собственнику помещение и коммунальные услуги вносится ежемесячно до пятнадцатого числа месяца, следующего за истекшим месяцем.'
      ),
    ]),
    bodyParagraph([
      plain(
        'Данная плата для собственника включает в себя: 1) плату за содержание принадлежащего ему помещения, 2) взнос на капитальный ремонт, 3) плату за коммунальные услуги (ч. 2 ст. 154 ЖК РФ).'
      ),
    ]),
    isOpt2
      ? bodyParagraph([
          plain('Как следует из выписки по лицевому счету, по нежилому помещению '),
          field(premisesNumber, 'номер'),
          plain(' числится задолженность по взносам на капитальный ремонт в размере '),
          moneyField(housingPenalty.principalTotal, 'сумма'),
          plain(' руб.'),
        ])
      : bodyParagraph([
          plain('Как следует из выписки по лицевому счету, по нежилому помещению '),
          field(premisesNumber, 'номер'),
          plain(
            ' числится задолженность за услуги по управлению и текущему ремонту общего имущества в размере '
          ),
          moneyField(housingPenalty.principalTotal, 'сумма'),
          plain(' руб.'),
        ]),
    bodyParagraph([
      plain('В связи с чем своевременная оплата такой задолженности является обязанностью собственника.'),
    ]),
    isOpt2
      ? bodyParagraph([
          plain(
            'Поскольку данная задолженность им просрочена, частью 14.1 статьи 155 ЖК РФ для собственника, несвоевременно и (или) не полностью уплатившего взносы на капитальный ремонт,'
          ),
        ])
      : bodyParagraph([
          plain(
            'Поскольку данная задолженность им просрочена, частью 14 статьи 155 ЖК РФ для собственника, несвоевременно и (или) не полностью внесшего плату за содержание принадлежащего ему помещения,'
          ),
        ]),
    bodyParagraph([
      plain(
        'предусмотрена законная пеня в размере 1/300 ключевой ставки Банка России от невыплаченной в срок суммы за каждый день просрочки, начиная с 31 дня, следующего за днем наступления установленного срока оплаты, по день фактической оплаты.'
      ),
    ]),
    ...(showKeyRateOnDecision
      ? [
          bodyParagraph([
            plain(
              'В соответствии с разъяснениями в ответе на 3 вопрос в «Обзоре судебной практики Верховного Суда РФ № 3 (2016)» расчет такой пени производится исходя из ключевой ставки, действующей на дату вынесения судом решения.'
            ),
          ]),
        ]
      : []),
    bodyParagraph([
      plain('По расчету истца (прилагается) сумма такой пени составляет '),
      moneyField(housingPenalty.penaltyTotal, 'размер'),
      plain(' руб.'),
    ]),
    ...(hasDebt
      ? [
          bodyParagraph([
            plain(
              'По смыслу ст. 330 ГК РФ, истец вправе требовать присуждения неустойки по день фактического исполнения обязательства, о чем указано в п. 65 Постановления Пленума Верховного Суда РФ от 24.03.2016 № 7.'
            ),
          ]),
        ]
      : []),
    bodyParagraph([plain('На основании изложенного, а также ст. 125, 126 АПК РФ,')]),

    { text: 'ПРОШУ:', alignment: 'center', bold: true, margin: [0, 12, 0, 12] },

    bodyParagraph([
      plain('- взыскать с '),
      field(debtorNames || ownerName, 'такого-то'),
      plain(' задолженность в размере '),
      moneyField(housingPenalty.principalTotal, 'сумма'),
      plain(' руб., пеню за период с '),
      field(penaltyRange.from, 'дата'),
      plain(' по '),
      field(penaltyRange.to, 'дата'),
      plain(' в размере '),
      moneyField(housingPenalty.penaltyTotal, 'сумма'),
      plain(' руб., продолжив начисление пени с '),
      field(continueFrom, 'дата'),
      plain(' по день фактической оплаты долга '),
      moneyField(housingPenalty.principalTotal, 'сумма'),
      plain(
        ' руб., исходя из 1/300 ключевой ставки Банка России от суммы задолженности за каждый день просрочки, а также расходы по уплате госпошлины в размере '
      ),
      label(ARBITRATION_CLAIM_DUTY),
      plain(' руб.'),
    ]),

    { text: 'Приложения:', margin: [24, 12, 0, 4] },
    { text: '1) почтовая квитанция о направлении заявления в адрес ответчика,', margin: [24, 0, 0, 0] },
    {
      text: [
        plain('2) доказательства уплаты госпошлины в размере '),
        label(ARBITRATION_CLAIM_DUTY),
        plain(' руб.,'),
      ],
      margin: [24, 0, 0, 0],
    },
    { text: '3) выписка из ЕГРН,', margin: [24, 0, 0, 0] },
    { text: '4) выписка по лицевому счету,', margin: [24, 0, 0, 0] },
    { text: '5) расчет пени,', margin: [24, 0, 0, 0] },
    { text: '6) выписки из ЕГРЮЛ и/или ЕГРИП на сторон,', margin: [24, 0, 0, 0] },
    { text: '7) копия доверенности представителя.', margin: [24, 0, 0, 0] },

    { text: [field(signerFio, 'ФИО подписанта')], margin: [24, 24, 0, 0] },
  ];

  return {
    content,
    defaultStyle: { fontSize: 11 },
    pageMargins: [56, 56, 56, 56],
  };
}
