/**
 * Фразы услуг для макетов «с 1 по 8» (мировой / район).
 * Источник: матрица вставок к «приказ для мирового - с 1 по 8» / проект приказа.
 * Без отсебятины — только опции, которые есть в матрице.
 */

/** Опции ЖКУ (население/УК), кроме 1 и 2. */
export const UTILITY_OPTS_1_TO_8 = ['3.1', '5.1', '6.1', '6.3', '7.1', '8.1', '8.2'];

/** ТКО — ставка 1/130. */
export function isTkoRequirements(requirements) {
  return requirements === '8.1' || requirements === '8.2';
}

/** Адрес дома без квартиры (плейсхолдер матрицы «адрес без квартиры»). */
export function addressWithoutFlat(address) {
  const text = String(address || '')
    .replace(/\u00a0/g, ' ')
    .trim();
  if (!text) return '';
  return text
    .replace(/,?\s*(?:кв\.?|квартира)\s*[0-9A-Za-zА-Яа-я/-]+\s*$/i, '')
    .replace(/,\s*$/, '')
    .trim();
}

/**
 * После имени взыскателя: «… исполняет обязанности / обеспечивает поставку … по адресу:».
 * Опция 2 в матрице отдельной вводной не имеет — как опция 1.
 */
export function introDutyAfterName(requirements) {
  switch (String(requirements || '')) {
    case '3.1':
      return ' обеспечивает поставку электроэнергии в многоквартирный дом по адресу: ';
    case '5.1':
      return ' обеспечивает поставку тепловой энергии (отопления) и горячей воды в многоквартирный дом по адресу: ';
    case '6.1':
      return ' обеспечивает поставку холодной воды в многоквартирный дом по адресу: ';
    case '6.3':
      return ' обеспечивает поставку холодной воды и оказывает услугу по водоотведению в отношении многоквартирного дома по адресу: ';
    case '7.1':
      return ' обеспечивает поставку газа в многоквартирный дом по адресу: ';
    case '8.1':
    case '8.2':
      return ' оказывает услугу по обращению с ТКО в отношении многоквартирного дома по адресу: ';
    case '1':
    case '2':
    default:
      return ' исполняет обязанности по управлению и текущему ремонту в отношении многоквартирного дома по адресу: ';
  }
}

/**
 * Предмет долга в абзаце «числится задолженность … в размере».
 * Уже с предлогом («за …» / «по взносам …»).
 */
export function debtSubjectPhrase(requirements) {
  switch (String(requirements || '')) {
    case '2':
      return 'по взносам на капитальный ремонт общего имущества в МКД';
    case '3.1':
      return 'за электроэнергию';
    case '5.1':
      return 'за услугу по отоплению и горячую воду';
    case '6.1':
      return 'за холодную воду';
    case '6.3':
      return 'за холодную воду и услугу по водоотведению';
    case '7.1':
      return 'за газ';
    case '8.1':
    case '8.2':
      return 'за услугу по обращению с ТКО';
    case '1':
    default:
      return 'за услугу по управлению и текущему ремонту общего имущества';
  }
}

/**
 * Предмет в ПРОШУ / проекте приказа после «задолженности » / «задолженность ».
 */
export function claimSubjectPhrase(requirements) {
  switch (String(requirements || '')) {
    case '2':
      return 'по взносам на капитальный ремонт';
    case '3.1':
      return 'за электроэнергию';
    case '5.1':
      return 'за услугу по отоплению и горячую воду';
    case '6.1':
      return 'за холодную воду';
    case '6.3':
      return 'за холодную воду и услугу по водоотведению';
    case '7.1':
      return 'за газ';
    case '8.1':
    case '8.2':
      return 'за услугу по обращению с ТКО';
    case '1':
    default:
      return 'за содержание жилого помещения';
  }
}
